    def is_connected(x1, y1, x2, y2):
        if x1 == x2:
            for y in range(min(y1, y2), max(y1, y2) + 1):
                if grid[x1][y] == '.':
                    return True
            return False
        elif y1 == y2:
            for x in range(min(x1, x2), max(x1, x2) + 1):
                if grid[x][y1] == '.':
                    return True
            return False
        return False

    # Find all painted squares
    painted_squares = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                painted_squares.append((i, j))

    # Check if it's already disconnected
    if len(painted_squares) == 1:
        return 0

    # Try to disconnect by removing each pair of painted squares
    min_deletions = float('inf')
    for i in range(len(painted_squares)):
